code.source:
#include <stdio.h>

int main() {
    int a = 17;
    int b = 5;

    printf("a + b = %d\n", a + b);
    printf("a - b = %d\n", a - b);
    printf("a * b = %d\n", a * b);
    printf("a / b = %d\n", a / b);
    printf("a %% b = %d\n", a % b);
    return 0;
}

#include <stdio.h>

int main() {
    int day = 30;
    int minutes = 135;

    printf("day %% 2 = %d\n", day % 2);
    printf("%d minutes = %d hours and %d minutes\n",
           minutes, minutes / 60, minutes % 60);
    printf("Last digit of 2026 = %d\n", 2026 % 10);
    return 0;
}

